<div class="modal fade app-confirm-modal" id="customerConfirmDialog" tabindex="-1" aria-labelledby="customerConfirmTitle" aria-describedby="customerConfirmText" aria-hidden="true">
    <div class="modal-dialog modal-dialog-centered"><div class="modal-content">
        <div class="modal-header"><span class="app-icon-tile"><i class="bi bi-shield-check" aria-hidden="true"></i></span><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close confirmation"></button></div>
        <div class="modal-body"><h2 id="customerConfirmTitle">Confirm your action</h2><p id="customerConfirmText"></p></div>
        <div class="modal-footer"><button type="button" class="btn btn-outline" data-bs-dismiss="modal">Keep listing</button><button type="button" class="btn btn-primary" data-confirm-accept>Withdraw listing</button></div>
    </div></div>
</div>
